package streamer

import("context";"os";"testing";"time";"github.com/shubhendu-abhishek/gpu-telemetry-pipeline/internal/queue";"github.com/shubhendu-abhishek/gpu-telemetry-pipeline/internal/telemetry")
type testPublisher struct{calls int}
func(p *testPublisher)PublishNext(_ context.Context,_ string,_ int64,_ queue.OffsetReader)(bool,error){p.calls++;return true,nil}
func TestRunStopsOnContext(t *testing.T){file:=t.TempDir()+"/input.csv";data:="timestamp,metric_name,gpu_id,device,uuid,modelName,Hostname,container,pod,namespace,value,labels_raw\n2025-07-18T20:42:34Z,UTIL,0,nvidia0,GPU-1,H100,host,,,,10,labels\n";if err:=os.WriteFile(file,[]byte(data),0600);err!=nil{t.Fatal(err)};source,err:=telemetry.OpenCSVSource(file);if err!=nil{t.Fatal(err)};defer source.Close();ctx,cancel:=context.WithCancel(context.Background());publisher:=&testPublisher{};service:=&Streamer{Publisher:publisher,Source:source,SourceID:"test",Interval:time.Millisecond};go func(){time.Sleep(10*time.Millisecond);cancel()}();if err:=service.Run(ctx);err!=nil{t.Fatal(err)};if publisher.calls==0{t.Fatal("expected at least one publish")}}
func TestRunRejectsInvalidConfiguration(t *testing.T){s:=&Streamer{Interval:time.Second};if err:=s.Run(context.Background());err==nil{t.Fatal("expected configuration error")}}
type configurablePublisher struct{result bool;err error;cancel context.CancelFunc;callReader bool}
func(p *configurablePublisher)PublishNext(_ context.Context,_ string,header int64,reader queue.OffsetReader)(bool,error){if p.callReader{if _,_,_,err:=reader(header);err!=nil{return false,err}};if p.cancel!=nil{p.cancel()};return p.result,p.err}
func TestRunPropagatesPublisherError(t *testing.T){source:=newTestSource(t);defer source.Close();want:=context.DeadlineExceeded;s:=&Streamer{Publisher:&configurablePublisher{err:want},Source:source,SourceID:"source",Interval:time.Millisecond};if err:=s.Run(context.Background());err!=want{t.Fatalf("got %v, want %v",err,want)}}
func TestRunTreatsPublisherErrorAfterCancellationAsShutdown(t *testing.T){source:=newTestSource(t);defer source.Close();ctx,cancel:=context.WithCancel(context.Background());p:=&configurablePublisher{err:context.Canceled,cancel:cancel};s:=&Streamer{Publisher:p,Source:source,SourceID:"source",Interval:time.Millisecond};if err:=s.Run(ctx);err!=nil{t.Fatalf("expected clean shutdown, got %v",err)}}
func TestRunHandlesNoPublishedRow(t *testing.T){source:=newTestSource(t);defer source.Close();ctx,cancel:=context.WithCancel(context.Background());p:=&configurablePublisher{cancel:cancel};s:=&Streamer{Publisher:p,Source:source,SourceID:"source",Interval:time.Millisecond};if err:=s.Run(ctx);err!=nil{t.Fatal(err)}}
func TestStreamerErrorMessage(t *testing.T){if errInvalidConfig.Error()==""{t.Fatal("empty error")}}
func newTestSource(t *testing.T)*telemetry.CSVSource{t.Helper();path:=t.TempDir()+"/source.csv";data:="timestamp,metric_name,gpu_id,device,uuid,modelName,Hostname,container,pod,namespace,value,labels_raw\n2025-07-18T20:42:34Z,UTIL,0,nvidia0,GPU-1,H100,host,,,,10,labels\n";if err:=os.WriteFile(path,[]byte(data),0600);err!=nil{t.Fatal(err)};source,err:=telemetry.OpenCSVSource(path);if err!=nil{t.Fatal(err)};return source}
func TestRunInvokesCSVReader(t *testing.T){source:=newTestSource(t);defer source.Close();ctx,cancel:=context.WithCancel(context.Background());p:=&configurablePublisher{result:true,cancel:cancel,callReader:true};s:=&Streamer{Publisher:p,Source:source,SourceID:"source",Interval:time.Second};if err:=s.Run(ctx);err!=nil{t.Fatal(err)}}
